function report=e3axPublishBehavioralTest(out)
% Informe visible en raíz de corrida, sin entrenar ni abrir el test sellado.
out=string(out);I=e3axCheckEvaluationFiles(out);
F=jsondecode(fileread(fullfile(out,"evaluation","final_summary.json")));
V=readtable(fullfile(out,"evaluation","comparison","VALIDATION","metrics.csv"),TextType="string",Delimiter=",");
T=readtable(fullfile(out,"evaluation","comparison","TRAIN","metrics.csv"),TextType="string",Delimiter=",");
C=readtable(fullfile(out,"checkpoint_validation.csv"),TextType="string",Delimiter=",");
S=readtable(fullfile(out,"evaluation_selection.csv"),TextType="string",Delimiter=",");
ranked=sortrows(C,["reward","mse","episode"],["descend","ascend","ascend"]);
assert(F.bestEpisode==ranked.episode(1) && F.lastEpisode==max(C.episode),"E3AX:CheckpointSelection","Selección BEST/LAST inconsistente.");
report=struct("status","COMPLETE","testType","POLICY_EVALUATION_TRAIN_VALIDATION","trainingExecuted",false, ...
    "finalTestExecuted",false,"sealedSubjects",["MATEO","SANDRA"],"referenceContractValidated",false, ...
    "bestEpisode",F.bestEpisode,"lastEpisode",F.lastEpisode,"episodesPerCheckpoint",height(S), ...
    "trainEpisodesPerCheckpoint",nnz(S.split=="TRAIN"),"validationEpisodesPerCheckpoint",nnz(S.split=="VALIDATION"), ...
    "pngCount",height(I),"figCount",height(I),"html",fullfile(out,"TEST_COMPORTAMENTAL.html"), ...
    "markdown",fullfile(out,"TEST_COMPORTAMENTAL.md"),"qualityDecision","DESCRIPTIVE_NO_NEW_PASS_GATE");
writetable(I,fullfile(out,"evaluation","episode_figure_index.csv"));
md=["# Test comportamental E3A-X";"";"**Evaluación completada y archivos verificados.**";""; ...
    "Esta evaluación usa TRAIN y VALIDATION de DEVELOPMENT. No es el test final sellado ni la batería matlab.unittest. MATEO/SANDRA no se han abierto.";""; ...
    "BEST: episodio "+F.bestEpisode+" (selección sólo por reward macro VALIDATION). LAST: episodio "+F.lastEpisode+"."; ...
    compose("Cada checkpoint: %d episodios TRAIN y %d VALIDATION. Total: %d PNG y %d FIG, cuatro motores por figura.",report.trainEpisodesPerCheckpoint,report.validationEpisodesPerCheckpoint,height(I),height(I));""; ...
    "[Abrir galería filtrable de TODOS los episodios](TEST_COMPORTAMENTAL.html)";""; ...
    "Inferencia EMG-only; teacher original sólo para métricas posteriores en el horizonte común. La referencia física sigue NO VALIDADA. P2 y Oracle son privilegiados; Agent7250 es diagnóstico histórico.";""; ...
    "## Resultados VALIDATION";"";metricMarkdown(V);"";"## Resultados TRAIN";"";metricMarkdown(T);""; ...
    "MSE/reward son medias macro históricas; reward usa tracking + penalización de acción .01 + cambio .05. La tabla de métricas conserva los términos separados, MAE, correlación, flat_response y action_no_motion."; ...
    "Ciclos y retrocesos M3 son conteos de eventos, no porcentajes. Cero ciclos finales no demuestra estabilidad universal.";""; ...
    "## Evidencia y protocolo";""; ...
    "- [Métricas VALIDATION](evaluation/comparison/VALIDATION/metrics.csv) y [TRAIN](evaluation/comparison/TRAIN/metrics.csv)."; ...
    "- [Curva de validación por checkpoint](checkpoint_validation.csv)."; ...
    "- [Índice por episodio con MSE/reward y enlaces PNG/FIG](evaluation/episode_figure_index.csv)."; ...
    "- [Curva de entrenamiento reproducible](training_progress.png)."; ...
    "- [Comparación final VALIDATION](evaluation/comparison/VALIDATION/policy_comparison.png).";""; ...
    "COMPLETADO significa que la evaluación y sus figuras existen. No implica que el controlador sea apto para hardware ni cambia el cierre científico de E2G."];
writeText(report.markdown,join(md,newline));
html=["<!doctype html><html lang='es'><meta charset='utf-8'><title>Test comportamental E3A-X</title>"; ...
    "<style>body{font:16px system-ui;margin:28px auto;max-width:1400px;padding:0 20px;background:#f6f7f9;color:#202735}h1{margin-bottom:8px}table{border-collapse:collapse;width:100%;background:white;margin:16px 0}th,td{padding:9px;text-align:left;border-bottom:1px solid #ddd}th{background:#e7edf6}a{color:#145fb0}select{padding:9px;margin:6px 16px 6px 4px}.note{padding:15px;background:#fff2d5;border-left:4px solid #cf8d15}.overview{max-width:100%;height:auto}small{color:#555}</style>"; ...
    "<h1>Test comportamental E3A-X — completado</h1><p>Evaluación de políticas en TRAIN / VALIDATION. <b>Test final MATEO/SANDRA sellado.</b></p>"; ...
    "<p>BEST episodio "+F.bestEpisode+" · LAST episodio "+F.lastEpisode+" · "+height(S)+" episodios por checkpoint · "+height(I)+" figuras con cuatro motores (PNG y FIG).</p>"; ...
    "<p class='note'>Referencia física NO validada. Este informe comprueba resultados y cobertura; no declara éxito de control. P2 y Oracle usan teacher privilegiado; TD3 se ejecuta sólo con EMG y estado mecánico.</p>"; ...
    "<p><a href='TEST_COMPORTAMENTAL.md'>Informe de texto</a> · <a href='evaluation/episode_figure_index.csv'>Índice CSV</a> · <a href='checkpoint_validation.csv'>Selección de checkpoint</a> · <a href='training_progress.png'>Entrenamiento</a></p>"; ...
    "<h2>VALIDATION — comparación de políticas</h2>";metricHTML(V); ...
    "<details><summary>Ver comparación TRAIN</summary>";metricHTML(T);"</details>"; ...
    "<h2>Figuras por episodio</h2><p>Cada PNG contiene M1, M2, M3 y M4: teacher original frente a h(q). FIG abre la misma figura editable en MATLAB. Los valores de acción están en CSV/MAT.</p>"; ...
    "<label>Conjunto <select id='split'><option value=''>Todos</option><option>VALIDATION</option><option>TRAIN</option></select></label>"; ...
    "<label>Checkpoint <select id='checkpoint'><option value=''>Ambos</option><option value='best_checkpoint'>BEST</option><option value='last_checkpoint'>LAST</option></select></label>"; ...
    "<label>Sujeto <select id='subject'><option value=''>Todos</option>"; ...
    join("<option>"+esc(unique(I.subject))+"</option>","");"</select></label><span id='count'></span>"; ...
    "<table id='episodes'><thead><tr><th>Checkpoint</th><th>Conjunto</th><th>Sujeto</th><th>Fila</th><th>Dirección</th><th>MSE</th><th>Reward</th><th>Figura de 4 motores</th></tr></thead><tbody>"];
for k=1:height(I)
    x=I(k,:);label="BEST";if x.checkpoint=="last_checkpoint",label="LAST";end
    html(end+1)="<tr data-split='"+x.split+"' data-checkpoint='"+x.checkpoint+"' data-subject='"+esc(x.subject)+"'><td>"+label+"</td><td>"+x.split+"</td><td>"+esc(x.subject)+"</td><td>"+x.row+"</td><td>"+x.direction+"</td><td>"+compose("%.6f",x.trackingMSE)+"</td><td>"+compose("%.6f",x.reward)+"</td><td><a target='_blank' href='"+esc(x.png)+"'>Abrir PNG</a> · <a href='"+esc(x.fig)+"'>FIG</a></td></tr>"; %#ok<AGROW>
end
html=[html;"</tbody></table><script>const keys=['split','checkpoint','subject'];function filter(){let n=0;document.querySelectorAll('#episodes tbody tr').forEach(r=>{let ok=keys.every(k=>!document.getElementById(k).value||r.dataset[k]===document.getElementById(k).value);r.hidden=!ok;if(ok)n++});document.getElementById('count').textContent=n+' episodios visibles'}keys.forEach(k=>document.getElementById(k).addEventListener('change',filter));filter();</script></html>"];
writeText(report.html,join(html,newline));
e2cWriteJSON(fullfile(out,"TEST_COMPORTAMENTAL.json"),report);
fprintf("TEST COMPORTAMENTAL COMPLETO: %d episodios por checkpoint; %d PNG + %d FIG.\nInforme: %s\n",height(S),height(I),height(I),report.html);
if usejava('desktop')
    quoted=replace(report.html,"'","''");
    fprintf('<a href="matlab:web(''%s'',''-browser'')">ABRIR TEST COMPORTAMENTAL Y FIGURAS POR EPISODIO</a>\n',quoted);
end
end
function lines=metricMarkdown(T)
lines=["| Política | MSE | Reward medio | Saturación | Ciclos finales | Retrocesos M3 |";"|---|---:|---:|---:|---:|---:|"];
for k=1:height(T),x=T(k,:);lines(end+1)=compose("| %s | %.6f | %.6f | %.2f%% | %d | %d |",x.controller,x.trackingMSE,x.rewardMean,100*x.saturationFraction,x.persistentTwoCycle,x.m3Reversals);end
end
function h=metricHTML(T)
h="<table><thead><tr><th>Política</th><th>MSE</th><th>Reward medio</th><th>Saturación</th><th>Ciclos finales</th><th>Retrocesos M3</th></tr></thead><tbody>";
for k=1:height(T),x=T(k,:);h=h+compose("<tr><td>%s</td><td>%.6f</td><td>%.6f</td><td>%.2f%%</td><td>%d</td><td>%d</td></tr>",esc(x.controller),x.trackingMSE,x.rewardMean,100*x.saturationFraction,x.persistentTwoCycle,x.m3Reversals);end
h=h+"</tbody></table>";
end
function s=esc(s)
s=replace(string(s),["&","<",">","'"],["&amp;","&lt;","&gt;","&#39;"]);
end
function writeText(file,s)
f=fopen(file,'w','n','UTF-8');assert(f>=0);c=onCleanup(@() fclose(f));fprintf(f,'%s',s); %#ok<NASGU>
end
